"""Русский язык, 2 класс."""
from rus_common import *


def t_speech(r):
    t = []
    t.append(ch("Какая речь звучит, её слушают?", "устная", ["письменная", "внутренняя"], "Устную речь произносят и слушают.", "Подумай: ушами или глазами?"))
    t.append(ch("Какую речь пишут и читают?", "письменная", ["устная", "мимика"], "Письменную речь записывают буквами и читают.", "Нужны буквы."))
    t.append(sort_("Разложи: где устная речь, а где письменная?", [("Устная", ["разговор по телефону", "ответ у доски", "песня"]), ("Письменная", ["письмо бабушке", "запись в дневнике", "книга"])],
                   "Устная речь звучит, письменная записана.", "Её слышат или читают?"))
    t.append(tf("Когда мы читаем книгу, мы пользуемся письменной речью.", True, "Книга записана буквами — это письменная речь.", "Книгу читают глазами."))
    t.append(tf("Записка другу — это устная речь.", False, "Записку пишут, значит это письменная речь.", "Записку пишут или говорят?"))
    t.append(multi("Что помогает понять устную речь?", ["интонация", "громкость голоса", "мимика и жесты"], ["запятые", "абзацы"], "В устной речи помогают голос, интонация, мимика.", "Что слышно и видно у говорящего?"))
    t.append(ch("Как называется речь, которую мы произносим «про себя»?", "внутренняя", ["письменная", "громкая"], "Мысленную речь называют внутренней.", "Она звучит только в голове."))
    t.append(order("Расставь, как правильно вести себя, когда говоришь с другим человеком.", ["поздороваться", "сказать, что хочешь", "выслушать ответ", "поблагодарить"], "Вежливый разговор: приветствие, просьба, внимание к собеседнику, благодарность.", "Что делают в начале разговора?"))
    t.append(fix("Найди неверное слово: «Письмо читают ушами».", ["Письмо", "читают", "ушами"], 2, "глазами", ["ногами", "руками"], "Письменную речь воспринимают глазами.", "Чем читают?"))
    t.append(ch("Какой знак помогает в письменной речи показать конец предложения?", "точка", ["пробел", "ударение"], "Конец предложения на письме отмечают точкой (или ! ?).", "Он ставится в конце."))
    return t


def t_dialog(r):
    t = []
    t.append(ch("Как называется разговор двух или нескольких людей?", "диалог", ["монолог", "рассказ"], "Диалог — разговор двух и более собеседников.", "«Ди» — два."))
    t.append(ch("Как называется речь одного человека?", "монолог", ["диалог", "спор"], "Монолог — речь одного человека.", "«Моно» — один."))
    t.append(ch("Каким знаком на письме обозначают слова собеседника в диалоге?", "тире", ["запятая", "двоеточие в конце"], "Реплики в диалоге начинаются с тире.", "Короткая черта в начале строки."))
    t.append(sort_("Разложи: диалог или монолог?", [("Диалог", ["разговор мамы и сына", "беседа в классе"]), ("Монолог", ["рассказ ученика у доски", "сказка, которую читает бабушка"])],
                   "Говорит один — монолог, несколько — диалог.", "Сколько человек говорят?"))
    t.append(order("Восстанови диалог по порядку.", ["— Привет! Куда идёшь?", "— В библиотеку.", "— Можно с тобой?", "— Конечно, пойдём!"], "Реплики отвечают друг на друга.", "С чего начинается разговор?"))
    t.append(tf("В диалоге каждую реплику начинают с новой строки.", True, "Так легче понять, кто говорит.", "Посмотри, как записывают диалоги в книгах."))
    t.append(multi("Какие правила помогают вести диалог?", ["слушать собеседника", "не перебивать", "говорить вежливо"], ["кричать", "говорить одновременно"], "Это правила вежливого общения.", "Как бы ты хотел, чтобы с тобой говорили?"))
    t.append(ch("Как называют слова одного собеседника в диалоге?", "реплика", ["абзац", "заголовок"], "Высказывание собеседника — реплика.", "Слово начинается на «р»."))
    t.append(fill("Разговор двух человек — это ___.", "диалог", ["монолог", "текст"], "Двое говорят — диалог.", "Сколько собеседников?"))
    t.append(fix("Найди ошибку: «Монолог — это разговор двух людей».", ["Монолог", "—", "разговор", "двух", "людей"], 0, "Диалог", ["Текст", "Рассказ"], "Разговор двух людей — диалог.", "Моно — один."))
    return t


def t_text_signs(r):
    t = []
    t.append(ch("Что такое текст?", "несколько предложений, связанных по смыслу", ["любые слова подряд", "одно слово"], "Предложения текста связаны темой и мыслью.", "Связь по смыслу."))
    t.append(tf("Предложения «Наступила осень. Пожелтели листья. Птицы улетают на юг.» — это текст.", True, "Все предложения об одном — об осени.", "Они об одном и том же?"))
    t.append(tf("«Кот спит. Завтра контрольная. Самолёт летит быстро.» — это текст.", False, "Предложения ни о чём общем, это не текст.", "Есть ли общая тема?"))
    t.append(multi("Выбери признаки текста.", ["предложения связаны по смыслу", "у текста есть тема", "можно озаглавить"], ["все слова на одну букву", "в тексте одно слово"], "Признаки текста: тема, основная мысль, связь предложений, заголовок.", "Что объединяет предложения?"))
    t.append(order("Расставь предложения, чтобы получился текст.", ["Утром Миша пошёл в лес.", "Он нашёл большой гриб.", "Миша принёс гриб маме.", "Мама похвалила сына."], "Последовательность событий.", "Что было сначала?"))
    t.append(ch("Какое предложение лишнее? «Ёжик живёт в лесу. Он ест жуков. На небе луна. Зимой ёжик спит.»", "На небе луна.", ["Ёжик живёт в лесу.", "Он ест жуков.", "Зимой ёжик спит."], "Текст о ёжике, а про луну — лишнее.", "О ком текст?"))
