    t.append(fix("Найди лишнее слово в заголовке текста о дружбе кошки и собаки: «Кошка и холодильник».", ["Кошка", "и", "холодильник"], 2, "собака", ["луна", "зима"], "Текст о дружбе кошки и собаки.", "О ком текст?"))
