def t_text_theme(r):
    t = []
    txt = "Наша Мурка любит играть. Она гоняет клубок по комнате. Ловит солнечных зайчиков. А потом сладко спит на диване."
    t.append(ch("О ком (о чём) этот текст? Это его тема.", "о кошке Мурке", ["о клубке", "о диване", "о солнце"], "Все предложения о кошке Мурке.", "Кто главный в тексте?", text=txt))
    t.append(ch("Какая главная мысль текста?", "Мурка любит играть", ["Диван мягкий", "Клубок круглый"], "Автор хочет сказать, что Мурка игривая.", "Что автор хочет сказать о Мурке?", text=txt))
    t.append(ch("Что такое тема текста?", "то, о ком или о чём говорится в тексте", ["последнее предложение", "самое длинное слово"], "Тема — о чём текст.", "О чём?"))
    t.append(ch("Что такое главная мысль?", "то, что хотел сказать автор", ["имя героя", "первое слово"], "Главная мысль — главное, что хочет сообщить автор.", "Что важное хотел сказать автор?"))
    txt2 = "Пришла зима. Снег укрыл землю. Дети катаются на санках и лепят снеговиков. Как весело зимой!"
    t.append(ch("Определи тему текста.", "зимние забавы", ["летний отдых", "школьные уроки"], "Текст о том, как весело зимой.", "Какое время года?", text=txt2))
    t.append(ch("Какой заголовок лучше отражает главную мысль?", "Весёлая зима", ["Снег", "Санки"], "Главная мысль: зимой весело.", "Последнее предложение подсказывает.", text=txt2))
    t.append(tf("Заголовок может выражать тему или главную мысль текста.", True, "Заголовок отражает тему или главную мысль.", "Для чего нужен заголовок?"))
    t.append(match("Соедини текст и его тему.", [("Про щенка, который потерялся и нашёлся", "Щенок"), ("Про первый снег", "Зима"), ("Про сбор урожая в огороде", "Осень")], "Тема — о чём текст.", "О чём рассказ?"))
    t.append(multi("Какие заголовки подходят к тексту о том, как мальчик помог бабушке?", ["Помощник", "Добрый внук"], ["Летний дождь", "Мой велосипед"], "Текст о помощи бабушке.", "О чём текст?"))
    t.append(fill("Главная ___ — это то, что хотел сказать автор.", "мысль", ["тема", "строчка"], "Главная мысль текста.", "Два слова: главная …"))
    return t


def t_text_parts(r):
    t = []
    t.append(order("Расставь части текста по порядку.", ["вступление", "основная часть", "заключение"], "Текст состоит из начала, основной части и концовки.", "Что в начале?"))
    t.append(ch("Как называется начало текста?", "вступление", ["заключение", "основная часть"], "Начало текста — вступление.", "Вступаем в текст."))
    t.append(ch("Как называется концовка текста?", "заключение", ["вступление", "заголовок"], "Концовка — заключение.", "Заключить — закончить."))
    t.append(ch("Как на письме выделяют части текста?", "красной строкой (абзацем)", ["большими буквами", "точками в середине"], "Каждая часть начинается с абзаца.", "Отступ в начале строки."))
    t.append(order("Восстанови текст.", ["Однажды Петя нашёл в парке птенца.", "Птенец выпал из гнезда и пищал.", "Петя осторожно положил его обратно в гнездо.", "Птица-мама радостно запела."], "Вступление, события, концовка.", "Как начинается история?"))
    t.append(sort_("Что подходит для вступления, а что для заключения?", [("Вступление", ["Жил-был кот Барсик.", "Однажды летом мы поехали на речку."]), ("Заключение", ["Вот так Барсик стал героем.", "Это было лучшее лето!"])], "Вступление начинает, заключение подводит итог.", "Начало или итог?"))
    t.append(tf("В основной части рассказывается главное событие.", True, "Основная часть — самая большая, в ней главные события.", "Где самое интересное?"))
    t.append(fill("Красная строка — это отступ в начале ___.", "абзаца", ["слова", "буквы"], "Абзац начинают с красной строки.", "Часть текста."))
    t.append(match("Соедини часть текста и её роль.", [("вступление", "знакомит с героями"), ("основная часть", "рассказывает о событиях"), ("заключение", "подводит итог")], "Роль частей текста.", "Начало, середина, конец."))
    t.append(fix("Найди ошибку: «Текст заканчивается вступлением».", ["Текст", "заканчивается", "вступлением"], 2, "заключением", ["заголовком", "абзацем"], "Текст заканчивается заключением.", "Конец текста — …"))
    return t


def t_sent_types(r):
    t = []
    for s, a in [("Как красиво в лесу", "!"), ("Ты сделал уроки", "?"), ("Мы гуляли в парке", "."), ("Когда начнутся каникулы", "?"), ("Ура, победа", "!")]:
        t.append(fill(f"Поставь знак в конце: «{s}___»", a, [x for x in [".", "?", "!"] if x != a], {"!": "Предложение произносится с сильным чувством — ставим «!».", "?": "Это вопрос — ставим «?».", ".": "Спокойное сообщение — точка."}[a], "Как это предложение произносят?"))
    t.append(ch("С какой буквы пишется первое слово предложения?", "с заглавной", ["со строчной", "с любой"], "Предложение начинается с заглавной буквы.", "Большая или маленькая?"))
    t.append(ch("Что такое предложение?", "слово или несколько слов, выражающих законченную мысль", ["любой набор букв", "только одно слово"], "Предложение выражает законченную мысль.", "Мысль должна быть закончена."))
    t.append(build("Составь предложение из слов: «зайчик, в, живёт, лесу»", ["Зайчик", "живёт", "в", "лесу."], ["Лесу"], "Зайчик живёт в лесу.", "С кого начать?"))
    t.append(sort_("Предложение или нет?", [("Предложение", ["Идёт дождь.", "Мама читает книгу."]), ("Не предложение", ["Дождь книга идёт", "Читает мама в"])], "Предложение выражает законченную мысль.", "Понятен ли смысл?"))
    t.append(fix("Найди ошибку: «петя пошёл в школу.»", ["петя", "пошёл", "в", "школу."], 0, "Петя", ["ПЕТЯ", "петя,"], "Первое слово предложения и имя пишутся с заглавной.", "Начало предложения."))
    return t


def t_main_members(r):
    t = []
    data = [("Кошка спит.", "Кошка", "спит"), ("Солнце светит ярко.", "Солнце", "светит"), ("Дети играют во дворе.", "Дети", "играют"), ("Птицы летят на юг.", "Птицы", "летят"), ("Весело журчит ручей.", "ручей", "журчит")]
    for s, subj, pred in data[:3]:
        t.append(ch(f"Найди подлежащее в предложении: «{s}»", subj, [w.strip(".") for w in s.split() if w.strip(".") != subj][:3], f"Подлежащее отвечает на вопрос «кто?» или «что?» — «{subj}».", "О ком или о чём говорится?"))
    for s, subj, pred in data[3:]:
        t.append(ch(f"Найди сказуемое в предложении: «{s}»", pred, [w.strip(".") for w in s.split() if w.strip(".") != pred][:3], f"Сказуемое говорит, что делает подлежащее: «{pred}».", "Что делает?"))
    t.append(ch("На какие вопросы отвечает подлежащее?", "кто? что?", ["что делает?", "какой?"], "Подлежащее отвечает на вопросы «кто?» «что?».", "Это главный «кто» в предложении."))
    t.append(ch("На какие вопросы чаще всего отвечает сказуемое?", "что делает? что сделал?", ["кто? что?", "какой? чей?"], "Сказуемое показывает действие.", "Действие."))
    t.append(ch("Как подчёркивают подлежащее?", "одной чертой", ["двумя чертами", "волнистой линией"], "Подлежащее — одна черта, сказуемое — две.", "Одна или две?"))
    t.append(match("Соедини подлежащее и сказуемое.", [("Ветер", "дует"), ("Собака", "лает"), ("Снег", "идёт"), ("Колокольчик", "звенит")], "Подлежащее и сказуемое — главные члены.", "Кто что делает?"))
    t.append(multi("Выбери главные члены в предложении «Маленький котёнок пьёт молоко».", ["котёнок", "пьёт"], ["маленький", "молоко"], "Кто? — котёнок, что делает? — пьёт.", "Основа: кто и что делает."))
    t.append(fix("Найди ошибку: «В предложении „Мальчик рисует“ сказуемое — мальчик».", ["сказуемое", "—", "мальчик"], 2, "рисует", ["предложение", "мальчики"], "«Рисует» — сказуемое, «мальчик» — подлежащее.", "Что делает?"))
    return t


