    t.append(fill("Слово «семья» переносим так: ___", "се-мья", ["сем-ья", "семь-я"], "Ь не отрываем от согласной: се-мья.", "Ь остаётся с согласной."))
    t.append(fix("Найди неправильный перенос в ряду.", ["лам-па", "пись-мо", "о-сень"], 2, "не переносится", ["ос-ень", "осе-нь"], "Одну букву нельзя оставлять на строке, а часть без гласной нельзя переносить, поэтому слово «осень» не переносится.", "Одну букву не оставляют."))
    return t


