def t_preposition(r):
    t = []
    for s, a, d in [("Книга лежит ___ столе.", "на", ["под", "из"]), ("Кот спрятался ___ диваном.", "под", ["над", "в"]), ("Птица вылетела ___ гнезда.", "из", ["в", "на"]), ("Мы пошли ___ лес.", "в", ["из", "под"])]:
        t.append(fill(s, a, d, f"Предлог «{a}» подходит по смыслу.", "Где? Куда? Откуда?"))
    t.append(ch("Как пишутся предлоги со словами?", "раздельно", ["слитно", "через дефис"], "Предлоги пишутся отдельно от других слов.", "Пробел."))
    t.append(fix("Найди ошибку: «Мы гуляли впарке».", ["Мы", "гуляли", "впарке"], 2, "в парке", ["в-парке", "впарки"], "Предлог «в» пишется раздельно.", "Предлог — отдельно."))
    t.append(multi("Выбери предлоги.", ["в", "над", "под"], ["дом", "и", "бег"], "Предлоги: в, на, под, над, из, к, от, у…", "Маленькие служебные слова."))
    t.append(ch("Как проверить, что «на» — предлог?", "вставить между ним и словом другое слово: на (высоком) столе", ["поставить ударение", "написать слитно"], "Между предлогом и словом можно вставить слово.", "Попробуй вставить «большом»."))
    t.append(build("Составь: «под, гриб, ёлкой, вырос».", ["Под", "ёлкой", "вырос", "гриб."], [], "Под ёлкой вырос гриб.", "Где вырос?"))
    t.append(tf("Предлог — это часть речи, которая служит для связи слов.", True, "Предлоги связывают слова в предложении.", "Служебная часть речи."))
    return t
